/** Cleans raw Gemini art and installs it into the game.
 *
 *  1. Raw images live in art-src/raw/ (generated by scripts/gem-gen.mjs from art-src/jobs-*.json).
 *  2. Run `npm run art`.
 *
 *  Sprites: the flat magenta backdrop is removed (edge flood-fill + enclosed pockets + pink fringe),
 *  trimmed and resized. Backgrounds are cropped to size. Output: public/art/*.webp, which the game
 *  loads automatically (anything missing falls back to the built-in shape art). */
import fs from 'node:fs';
import path from 'node:path';
import sharp from 'sharp';

const RAW = path.resolve('art-src/raw');
const OUT = path.resolve('public/art');

// name pattern -> max output size (longest side) for sprites
const SPRITES = [
  [/^kaiju-\d+$/, 320],
  [/^kaiju-\d+-rage$/, 360],
  [/^cut-[a-z]+$/, 160],
  [/^ob-[a-z]+$/, 320],
  [/^hand$/, 640],
  [/^cleaver$/, 640],
  [/^mat-[a-z]+$/, 320],
  [/^toast$/, 96],
  [/^lazysusan$/, 640],
  [/^spoon$/, 420],
];
const TABLES = ['bg-table', 'bg-sushi', 'bg-party', 'bg-board', 'bg-griddle', 'bg-parlour', 'bg-picnic', 'bg-bakery', 'bg-banquet', 'bg-breakfast', 'bg-freezer', 'bg-candy', 'bg-nightmare', 'bg-smoothie']; // table surfaces get rounded corners
const CUTS = ['cut-open', 'cut-end', ...Array.from({ length: 12 }, (_, i) => `cut-${i}`)]; // story cutscene stills (video posters)
const BACKGROUNDS = { ...Object.fromEntries(CUTS.map(c => [c, [1280, 720]])), 'bg-floor': [1280, 720], 'bg-menu': [1280, 720], 'bg-title': [1280, 720], 'bg-story': [1280, 720], ...Object.fromEntries(TABLES.map(t => [t, [1080, 575]])) };

fs.mkdirSync(OUT, { recursive: true });
const files = fs.existsSync(RAW) ? fs.readdirSync(RAW).filter(f => /\.(png|jpe?g|webp)$/i.test(f)) : [];
if (!files.length) {
  console.log(`No images in ${RAW}.`);
  process.exit(0);
}

function removeBackground(data, w, h) {
  const at = (x, y) => (y * w + x) * 4;
  const corners = [at(2, 2), at(w - 3, 2), at(2, h - 3), at(w - 3, h - 3)];
  const ref = corners.map(i => [data[i], data[i + 1], data[i + 2]]);
  const near = (i, tol) => ref.some(([R, G, B]) => Math.abs(data[i] - R) + Math.abs(data[i + 1] - G) + Math.abs(data[i + 2] - B) < tol);
  const magentaish = i => data[i] > 150 && data[i + 2] > 150 && data[i + 1] < 130 && Math.abs(data[i] - data[i + 2]) < 90;

  const mark = new Uint8Array(w * h);
  const queue = [];
  const push = (x, y) => {
    const p = y * w + x;
    if (mark[p] || !near(p * 4, 90)) return;
    mark[p] = 1;
    queue.push(p);
  };
  for (let x = 0; x < w; x++) { push(x, 0); push(x, h - 1); }
  for (let y = 0; y < h; y++) { push(0, y); push(w - 1, y); }
  while (queue.length) {
    const p = queue.pop(), x = p % w, y = (p / w) | 0;
    if (x > 0) push(x - 1, y);
    if (x < w - 1) push(x + 1, y);
    if (y > 0) push(x, y - 1);
    if (y < h - 1) push(x, y + 1);
  }
  // enclosed pockets of backdrop (e.g. between a claw and the body)
  for (let p = 0; p < w * h; p++) if (!mark[p] && near(p * 4, 45)) mark[p] = 1;
  // pink fringe: magenta-tinted pixels touching the removed area (2 passes)
  for (let pass = 0; pass < 2; pass++) {
    const add = [];
    for (let p = 0; p < w * h; p++) {
      if (mark[p]) continue;
      const x = p % w, y = (p / w) | 0;
      const touching = (x > 0 && mark[p - 1]) || (x < w - 1 && mark[p + 1]) || (y > 0 && mark[p - w]) || (y < h - 1 && mark[p + w]);
      if (touching && magentaish(p * 4)) add.push(p);
    }
    for (const p of add) mark[p] = 1;
  }
  for (let p = 0; p < w * h; p++) {
    if (mark[p]) { data[p * 4 + 3] = 0; continue; }
    const x = p % w, y = (p / w) | 0;
    const edge = (x > 0 && mark[p - 1]) || (x < w - 1 && mark[p + 1]) || (y > 0 && mark[p - w]) || (y < h - 1 && mark[p + w]);
    if (edge) data[p * 4 + 3] = Math.min(data[p * 4 + 3], 170);
  }
}

function bbox(data, w, h, x0 = 0, x1 = w) {
  let l = w, t = h, r = -1, b = -1;
  for (let y = 0; y < h; y++)
    for (let x = x0; x < x1; x++)
      if (data[(y * w + x) * 4 + 3] > 24) { if (x < l) l = x; if (x > r) r = x; if (y < t) t = y; if (y > b) b = y; }
  return r < 0 ? null : { left: l, top: t, width: r - l + 1, height: b - t + 1 };
}

async function saveSprite(data, info, box, name, max) {
  const out = await sharp(data, { raw: { width: info.width, height: info.height, channels: 4 } })
    .extract(box)
    .resize({ width: max, height: max, fit: 'inside', withoutEnlargement: true })
    .webp({ quality: 88, alphaQuality: 95 })
    .toFile(path.join(OUT, `${name}.webp`));
  console.log(`OK ${name}.webp ${out.width}x${out.height}`);
}

for (const file of files) {
  const name = path.basename(file, path.extname(file)).toLowerCase();
  const src = path.join(RAW, file);
  if (BACKGROUNDS[name]) {
    const [w, h] = BACKGROUNDS[name];
    let img = sharp(src).resize({ width: w, height: h, fit: 'cover' });
    if (TABLES.includes(name)) {
      // round the corners to match the table outline drawn in-game (radius 22)
      const mask = Buffer.from(`<svg width="${w}" height="${h}"><rect width="${w}" height="${h}" rx="22" ry="22" fill="#fff"/></svg>`);
      img = sharp(await img.png().toBuffer()).composite([{ input: mask, blend: 'dest-in' }]);
    }
    await img.webp({ quality: 84, alphaQuality: 90 }).toFile(path.join(OUT, `${name}.webp`));
    console.log(`OK ${name}.webp (background ${w}x${h})`);
    continue;
  }
  const spec = SPRITES.find(([re]) => re.test(name));
  if (!spec && name !== 'crumbs') { console.log(`? skipped ${file}`); continue; }
  const { data, info } = await sharp(src).ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  removeBackground(data, info.width, info.height);
  if (name === 'crumbs') {
    // three bits left-to-right -> crumb-0 (bread), crumb-1 (pea), crumb-2 (rice)
    for (let i = 0; i < 3; i++) {
      const x0 = Math.floor((info.width * i) / 3), x1 = Math.floor((info.width * (i + 1)) / 3);
      const box = bbox(data, info.width, info.height, x0, x1);
      if (box) await saveSprite(data, info, box, `crumb-${i}`, 64);
    }
    continue;
  }
  const box = bbox(data, info.width, info.height);
  if (!box) { console.log(`! ${file}: everything was removed`); continue; }
  await saveSprite(data, info, box, name, spec[1]);
}

// The game loads exactly what's listed here (so a missing image never causes a 404).
const manifest = fs.readdirSync(OUT).filter(f => f.endsWith('.webp')).map(f => f.replace(/\.webp$/, '')).sort();
fs.writeFileSync(path.join(OUT, 'manifest.json'), JSON.stringify(manifest, null, 1) + '\n');
console.log(`manifest: ${manifest.length} images`);
